SELECT game_id AS "gameId", modifier_id AS "modifierId", provider_id AS "providerId", modifier_key AS "modifierKey", modifier_type_id AS "modifierTypeId", target_selector_type_id AS "targetSelectorTypeId", target_attr_key AS "targetAttrKey", command_type_id AS "commandTypeId", channel_type_id AS "channelTypeId", bucket_type_id AS "bucketTypeId", stage_type_id AS "stageTypeId", priority AS priority, value_policy_type_id AS "valuePolicyTypeId", value_formula_key AS "valueFormulaKey", condition_formula_key AS "conditionFormulaKey", change_revision AS "changeRevision", updated_at AS "updatedAt" FROM public.provider_modifiers WHERE game_id = #{gameId}
AND provider_id = #{providerId}
ORDER BY provider_id, modifier_id
